entries[1219206] = { ["name"] = "Hand der Abrechnung", ["text"] = "Nahkampfreichweite\nSofort 10 sek. Abklingzeit\nVerspottet das Ziel, damit es Euch angreift. Hat keinen Effekt, wenn Ihr von dem Ziel bereits angegriffen werdet.\n\nWährend Ihr diese Fähigkeit kennt, ist der Bedrohungsbonus von 'Zorn der Gerechtigkeit' auf 80% erhöht. Wenn Ihr von anderen Charakteren geheilt werdet, sorgt 'Zorn der Gerechtigkeit' dafür, dass Ihr Mana in Höhe von 25% der hervorgerufenen Heilung erhaltet. Zusätzlich wird Schaden, der Eure Gesundheit unter 35% senkt, um 20% verringert, während 'Zorn der Gerechtigkeit' aktiv ist. 'Zorn der Gerechtigkeit' bleibt aktiv, bis er abgebrochen wird." }
entries[1219229] = { ["name"] = "Überladen", ["text"] = "Sofort\nDas Konstruktviertel wurde ermächtigt. Spielercharaktere werden nach dem Zufallsprinzip von energetisierenden Blitzen getroffen." }
