entries[1219500] = { ["name"] = "Kuss der Spinne", ["text"] = "Sofort\nErhöht Euer Angriffstempo 15 Sek. lang um 20%." }
entries[1219501] = { ["name"] = "Loathebs Abglanz", ["text"] = "Sofort\nReflektiert den nächsten Offensivzauber gegen den Anwender und erhöht 15 Sek. lang den Widerstand gegen alle Arten von Magie um 40." }
entries[1219503] = { ["name"] = "Das Auge des Schwunds", ["text"] = "Sofort\nVerringert Eure Größe und die von Euch verursachte Bedrohung 20 Sek. lang um 70%." }
entries[1219506] = { ["name"] = "Manazuwachs", ["text"] = "Sofort 1 min Abklingzeit\nStellt 6000 Mana wieder her." }
entries[1219507] = { ["name"] = "Unverwüstlichkeit der Geißel", ["text"] = "Wirken in 5 sek.\nBenötigt Schulterstücke\nFügt einem Gegenstand, der sich an einem Schulterplatz befindet, dauerhaft eine Erhöhung der Heilwirkung durch Zauber und magische Effekte um bis zu 31 hinzu und erhöht die Manaregeneration um 5 pro 5 Sek." }
entries[1219510] = { ["name"] = "Stärke der Geißel", ["text"] = "Wirken in 5 sek.\nBenötigt Schulterstücke\nFügt einem Gegenstand, der sich an einem Schulterplatz befindet, dauerhaft eine Erhöhung der Schadens- und Heilwirkung durch Zauber und magische Effekte um bis zu 15 hinzu und erhöht die kritische Trefferchance um 1%." }
entries[1219511] = { ["name"] = "Standhaftigkeit der Geißel", ["text"] = "Wirken in 5 sek.\nBenötigt Schulterstücke\nFügt einem Gegenstand, der sich an einem Schulterplatz befindet, dauerhaft eine Erhöhung der Ausdauer um 16 und der Verteidigung um 7 hinzu." }
entries[1219512] = { ["name"] = "Macht der Geißel", ["text"] = "Wirken in 5 sek.\nBenötigt Schulterstücke\nFügt einem Gegenstand, der sich an einem Schulterplatz befindet, dauerhaft eine Erhöhung der Angriffskraft um 26 hinzu und erhöht die Chance auf einen kritischen Treffer um 1%." }
entries[1219513] = { ["name"] = "Das Auge des Todes", ["text"] = "Sofort\nErhöht die durch die nächsten 5 Zauber verursachte Heilung um bis zu 450 Gesundheit. Hält 30 Sek. lang an." }
entries[1219515] = { ["name"] = "Essenz Saphirons", ["text"] = "Sofort\nErhöht den durch Zauber und magische Effekte verursachten Schaden und hervorgerufene Heilung 20 Sek. lang um bis zu 180." }
entries[1219519] = { ["name"] = "Wappen des Schlächters", ["text"] = "Sofort\nErhöht 20 Sek. lang die Angriffskraft um 280." }
entries[1219520] = { ["name"] = "Glyphe der Abwehr", ["text"] = "Sofort\nErhöht 20 Sek. lang den Blockwert Eures Schildes um 400." }
entries[1219521] = { ["name"] = "Held der Dämmerung", ["text"] = "+157 Angriffskraft im Kampf gegen Untote und Dämonen. Ermöglicht das Einsammeln von Geißelsteinen im Namen der Argentumdämmerung." }
entries[1219522] = { ["name"] = "Held der Dämmerung", ["text"] = "Erhöht den durch Zauber und magische Effekte Untoten und Dämonen zugefügten Schaden um bis zu 89. Ermöglicht das Einsammeln von Geißelsteinen im Namen der Argentumdämmerung." }
entries[1219539] = { ["name"] = "Siegel der Dämmerung", ["text"] = "Sofort\nEntfaltet Euer Potenzial, während Ihr in Naxxramas seid. Erhöht pro ausgerüstetem geweihten Gegenstand Euren Schaden um 1.25% und Eure Gesundheit um 1.25%. (Das Ausrüsten von mehr als 8 geweihten Gegenständen bringt keine weiteren Vorteile)" }
entries[1219541] = { ["name"] = "Spott", ["text"] = "Nahkampfreichweite\nSofort 10 sek. Abklingzeit\nBenötigt Verteidigungshaltung\nVerspottet das Ziel, damit es Euch angreift. Hat keinen Effekt, wenn Ihr von dem Ziel bereits angegriffen werdet." }
entries[1219548] = { ["name"] = "Siegel der Dämmerung", ["text"] = "Sofort\nEntfaltet Euer Potenzial, während Ihr in Naxxramas seid. Erhöht pro ausgerüstetem geweihten Gegenstand Eure Heilung um 1.25% und Eure Gesundheit um 1.25%. (Das Ausrüsten von mehr als 8 geweihten Gegenständen bringt keine weiteren Vorteile)" }
entries[1219552] = { ["name"] = "Macht des Wächters", ["text"] = "Sofort\nErhöht durch Zauber und magische Effekte verursachten Schaden und hervorgerufene Heilung aller Gruppenmitglieder innerhalb von 30 Metern um bis zu 33. Dieser spezifische Effekt ist nicht über mehrere Quellen stapelbar." }
entries[1219553] = { ["name"] = "Macht des Wächters", ["text"] = "Sofort\nErhöht für alle Gruppenmitglieder innerhalb von 30 Metern durch sämtliche Zauber und magische Effekte hervorgerufene Heilung um bis zu 62 Gesundheit und den verursachten Schaden um bis zu 19. Dieser spezifische Effekt ist nicht über mehrere Quellen stapelbar." }
entries[1219557] = { ["name"] = "Macht des Wächters", ["text"] = "Sofort\nErhöht das Zaubertempo aller Gruppenmitglieder innerhalb von 30 Metern um 2%. Dieser spezifische Effekt ist nicht über mehrere Quellen stapelbar." }
entries[1219558] = { ["name"] = "Macht des Wächters", ["text"] = "Sofort\nErhöht die kritische Zaubertrefferchance aller Gruppenmitglieder innerhalb von 30 Metern um 2%. Dieser spezifische Effekt ist nicht über mehrere Quellen stapelbar." }
entries[1219568] = { ["name"] = "Formel: Schildhand - Überragende Intelligenz", ["text"] = "Unbegrenzte Reichweite\nSofort\nLehrt Euch, wie man eine Schildhand dauerhaft so verzaubert, dass die Intelligenz um 9 erhöht wird." }
entries[1219569] = { ["name"] = "Formel: Schildhand - Ausgezeichnete Willenskraft", ["text"] = "Unbegrenzte Reichweite\nSofort\nLehrt Euch, wie man eine Schildhand dauerhaft so verzaubert, dass die Willenskraft um 12 erhöht wird." }
entries[1219570] = { ["name"] = "Formel: Schildhand - Weisheit", ["text"] = "Unbegrenzte Reichweite\nSofort\nLehrt Euch, wie man eine Schildhand dauerhaft so verzaubert, dass die Intelligenz um 6 und die Willenskraft um 5 erhöht wird." }
entries[1219571] = { ["name"] = "Formel: Zweihandwaffe - Zauberschlag", ["text"] = "Unbegrenzte Reichweite\nSofort\nLehrt Euch, wie man eine Zweihandwaffe dauerhaft so verzaubert, dass sie die Zaubermacht um 65 erhöht." }
entries[1219572] = { ["name"] = "Formel: Schild - Ausgezeichnete Ausdauer", ["text"] = "Unbegrenzte Reichweite\nSofort\nLehrt Euch, wie man einen Schild dauerhaft so verzaubert, dass die Ausdauer um 12 erhöht wird." }
entries[1219573] = { ["name"] = "Formel: Schild - Kritische Trefferchance", ["text"] = "Unbegrenzte Reichweite\nSofort\nLehrt Euch, wie man einen Schild dauerhaft so verzaubert, dass die kritische Trefferchance um 1% erhöht wird." }
entries[1219574] = { ["name"] = "Formel: Armschiene - Große Zaubermacht", ["text"] = "Unbegrenzte Reichweite\nSofort\nLehrt Euch, wie man Armschienen dauerhaft so verzaubert, dass sie die Zaubermacht um 16 erhöhen." }
entries[1219575] = { ["name"] = "Formel: Handschuhe - Überragende Stärke", ["text"] = "Unbegrenzte Reichweite\nSofort\nLehrt Euch, wie man Handschuhe dauerhaft so verzaubert, dass die Stärke um 15 erhöht wird." }
entries[1219576] = { ["name"] = "Formel: Umhang - Beweglichkeit", ["text"] = "Unbegrenzte Reichweite\nSofort\nLehrt Euch, wie man einen Umhang dauerhaft so verzaubert, dass er die Beweglichkeit um 5 erhöht." }
entries[1219577] = { ["name"] = "Schildhand - Überragende Intelligenz", ["text"] = "Wirken in 5 sek.\nBenötigt Rüstung\nTools: Runenverzierte Arkanitrute\nReagenzien:\nNexuskristall (2), Illusionsstaub (18), Essenz der Luft (2)\nSchildhand dauerhaft verzaubern, sodass die Intelligenz um 9 erhöht wird." }
entries[1219578] = { ["name"] = "Schildhand - Ausgezeichnete Willenskraft", ["text"] = "Wirken in 5 sek.\nBenötigt Rüstung\nTools: Runenverzierte Arkanitrute\nReagenzien:\nNexuskristall (2), Illusionsstaub (18), Essenz des Wassers (2)\nSchildhand dauerhaft verzaubern, sodass die Willenskraft um 12 erhöht wird." }
entries[1219579] = { ["name"] = "Schildhand - Weisheit", ["text"] = "Wirken in 5 sek.\nBenötigt Rüstung\nTools: Runenverzierte Arkanitrute\nReagenzien:\nGroßer glänzender Splitter (6), Illusionsstaub (18), Essenz der Luft , Essenz des Wassers\nSchildhand dauerhaft verzaubern, sodass die Intelligenz um 6 und die Willenskraft um 5 erhöht wird." }
entries[1219580] = { ["name"] = "Zweihandwaffe - Zauberschlag", ["text"] = "Wirken in 5 sek.\nTools: Runenverzierte Arkanitrute\nReagenzien:\nNexuskristall (3), Illusionsstaub (24), Blut von Helden , Lila Lotus (6)\nEine Zweihandwaffe dauerhaft verzaubern, sodass die Zaubermacht um 65 erhöht wird." }
entries[1219581] = { ["name"] = "Schild - Ausgezeichnete Ausdauer", ["text"] = "Wirken in 5 sek.\nBenötigt Rüstung\nTools: Runenverzierte Arkanitrute\nReagenzien:\nGroßer glänzender Splitter (6), Illusionsstaub (18), Essenz der Erde (2)\nEinen Schild dauerhaft verzaubern, sodass die Ausdauer um 12 erhöht wird." }
entries[1219586] = { ["name"] = "Handschuhe - Überragende Stärke", ["text"] = "Wirken in 5 sek.\nBenötigt Rüstung\nTools: Runenverzierte Arkanitrute\nReagenzien:\nGroße ewige Essenz (7), Illusionsstaub (21), Essenz des Feuers (2)\nHandschuhe dauerhaft verzaubern, sodass die Stärke um 15 erhöht wird." }
entries[1219587] = { ["name"] = "Umhang - Beweglichkeit", ["text"] = "Wirken in 5 sek.\nBenötigt Rüstung\nTools: Runenverzierte Arkanitrute\nReagenzien:\nGroße ewige Essenz (3), Illusionsstaub (9), Essenz des Feuers\nEinen Umhang dauerhaft verzaubern, sodass die Beweglichkeit um 5 erhöht wird." }
