entries[1219729] = { ["name"] = "Eiszeitliches Schmettern", ["text"] = "Sofort\nVerursacht nach Ablauf dieser Aura schweren Frostschaden, der zwischen allen Verbündeten in der Nähe aufgeteilt wird." }
entries[1219732] = { ["name"] = "Eiszeitliches Schmettern", ["text"] = "Sofort\nVerursacht nach Ablauf dieser Aura schweren Frostschaden, der zwischen allen Verbündeten in der Nähe aufgeteilt wird." }
