entries[1219740] = { ["name"] = "Seele des Taktikers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Taktikers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nNachdem Ihr die Haltung wechselt, sind die Wutkosten Eurer nächsten Offensivfähigkeit um 10 verringert." }
entries[1219741] = { ["name"] = "Haschende Geister", ["text"] = "Unbegrenzte Reichweite\nSofort\nVerursacht alle 1 Sek. 462 bis 538 Schattenschaden. Verringert die Bewegungsgeschwindigkeit um 35%." }
entries[1219742] = { ["name"] = "Seele des Kriegsveteranen", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Kriegsveteranen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nNach Verlassen einer Haltung könnt Ihr 15 Sek. lang noch Fähigkeiten nutzen, die diese Haltung erfordern." }
entries[1219743] = { ["name"] = "Seele des Kampfvoraussehers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Kampfvoraussehers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nWenn Ihr eine Haltung einnehmt, erhaltet Ihr für 15 Sek. einen weiteren Vorteil:\n\nKampfhaltung/Gladiatorhaltung: Verursachter Schaden um 5% erhöht.\n\nBerserkerhaltung: Kritische Trefferchance um 5% erhöht.\n\nVerteidigungshaltung: Erlittener körperlicher Schaden um 5% verringert." }
entries[1219744] = { ["name"] = "Haschende Geister" }
entries[1219745] = { ["name"] = "Seele des Blutsuchers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Blutsuchers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nKritische Treffer von 'Überwältigen' setzen die Dauer von 'Verwunden' auf Eurem Ziel auf die Höchstdauer zurück." }
entries[1219747] = { ["name"] = "Seele des Titanischen", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Titanischen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure Fähigkeiten 'Heldenhafter Stoß', 'Zerschmettern' und 'Überwältigen' verursachen 10 + (5 * Combopunkte)% mehr Schaden." }
entries[1219748] = { ["name"] = "Seele des Zerstörers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Zerstörers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure Treffer mit 'Zerschmettern' schließen die verbleibende Abklingzeit Eurer Fähigkeiten 'Tödlicher Stoß', 'Blutdurst' und 'Schildschlag' ab." }
entries[1219749] = { ["name"] = "Seele des Todesgebundenen", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Todesgebundenen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Abklingzeit Eurer Fähigkeit 'Todeswunsch' um 50%." }
entries[1219751] = { ["name"] = "Seele des Bluters", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Bluters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nIhr verursacht 15% mehr Schaden, während ein Gegner in der Nähe mit Euren Effekten 'Verwunden' und 'Tiefe Wunden' gleichzeitig belegt ist." }
entries[1219752] = { ["name"] = "Seele des makellosen Blockers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des makellosen Blockers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den Blockwert Eures Schildes um 30." }
entries[1219753] = { ["name"] = "Seele des Wilden", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Wilden wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nJedes Mal, wenn Ihr Schaden erleidet oder mit automatischen Angriffen Schaden verursacht, erzeugt Ihr zusätzlich 1 Wut." }
entries[1219754] = { ["name"] = "Seele der Feindseligkeit", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele der Feindseligkeit wird dauerhaft in Eure Schulterstücke eingepflanzt:\n\nErhöht Eure in der Verteidigungshaltung erzeugte Bedrohung um zusätzlich 10% und erhöht Euren in der Gladiatorhaltung verursachten Schaden um 4%." }
entries[1219755] = { ["name"] = "Seele des Parierenden", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Parierenden wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nIhr erhaltet jedes Mal 10 Wut, wenn Ihr einen Angriff pariert oder einer Eurer Angriffe pariert wird." }
entries[1219756] = { ["name"] = "Seele des Rächers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Rächers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\n'Rache' gewährt Euch 'Schlaghagel' und erhöht Euer Angriffstempo für die nächsten 3 Hiebe um 30%." }
entries[1219757] = { ["name"] = "Seele des Unermüdlichen", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Unermüdlichen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nWenn Euer Ziel einen Angriff pariert, holt Ihr sofort zum 'Gegenschlag' aus und fügt ihm 200% Waffenschaden zu. 'Gegenschlag' kann nicht ausgewichen, geblockt oder pariert werden, kann aber pro Ziel nur alle 30 Sek. vorkommen." }
entries[1219758] = { ["name"] = "Seele des Donnerbringers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Donnerbringers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Abklingzeit von 'Donnerknall' um 100%." }
entries[1219760] = { ["name"] = "Seele der Schildwache", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele der Schildwache wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer 'Schildschlag' verursacht 100% mehr Bedrohung und seine Abklingzeit wird abgeschlossen, wenn er pariert oder geblockt wird oder ihm ausgewichen wird." }
entries[1219762] = { ["name"] = "Seele des Rechtsauslegers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Rechtsauslegers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Abklingzeit Eurer Fähigkeit 'Schildschlag' um 2 Sek." }
entries[1219763] = { ["name"] = "Seele des Gladiators", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Gladiators wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Abklingzeit Eurer Fähigkeit 'Blutrausch' um 30 Sek., während Ihr in Gladiatorhaltung seid." }
entries[1219764] = { ["name"] = "Seele des Nachbebens", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Nachbebens wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Abklingzeit von 'Schockwelle' um 25%." }
entries[1219766] = { ["name"] = "Seele des Vermeidenden", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Vermeidenden wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\n'Finte' gewährt zusätzlich für 6 Sek. Vermeidung, was Euren durch Flächenangriffe von Gegnern außer Spielercharakteren erlittenen Schaden um 50% verringert." }
entries[1219767] = { ["name"] = "Seele des Toxikologen", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Toxikologen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den kritischen Schadensbonus Eurer Gifte um 100%." }
entries[1219768] = { ["name"] = "Seele des Scharfrichters", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Scharfrichters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure Finishing-Moves haben eine Chance von 5% pro Combopunkt, die Energiekosten Eurer nächsten Fähigkeit aufzuheben." }
entries[1219769] = { ["name"] = "Seele des Opportunisten", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Opportunisten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure Eröffnungsangriffe haben eine Chance von 100%, dass Eure nächste Fähigkeit keine Energie kostet." }
entries[1219770] = { ["name"] = "Seele des Schlächters", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Schlächters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den Schaden, den Eure Waffenhandwaffe durch Fähigkeiten verursacht, die Combopunkte erzeugen, um 20%." }
entries[1219771] = { ["name"] = "Seele des Phantoms", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Phantoms wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Abklingzeit von 'Verschwinden' auf 1 Min. Kann nicht mit 'Flüchtigkeit' kombiniert werden." }
entries[1219772] = { ["name"] = "Seele des Halunken", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Halunken wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den Schaden von 'Verstümmeln' und 'Säbelschlitzer' um 20%." }
entries[1219773] = { ["name"] = "Seele des Abenteuerlustigen", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Abenteuerlustigen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Abklingzeit von 'Adrenalinrausch' um 4 Min." }
entries[1219774] = { ["name"] = "Seele des Messerkenners", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Messerkenners wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht Eure Chance, mit Dolchen einen kritischen Treffer zu erzielen, um 5%." }
entries[1219775] = { ["name"] = "Seele des Pirschers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Pirschers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht die Chance auf einen kritischen Treffer Eurer Fähigkeit 'Hinterhalt' um 30%." }
entries[1219776] = { ["name"] = "Seele des Effizienten", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Effizienten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure Finishing-Moves kosten 50% weniger Energie." }
entries[1219777] = { ["name"] = "Seele des Messerjongleurs", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Messerjongleurs wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nWenn 'Nur eine Fleischwunde' und 'Klingentanz' aktiv sind, kosten 'Blutroter Sturm', 'Donnerbüchse' und 'Dolchfächer' 20 Energie weniger und erzeugen 100% mehr Bedrohung." }
entries[1219778] = { ["name"] = "Seele des Schattenmeisters", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Schattenmeisters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\n'Verschwinden' verringert während der Effektdauer sämtlichen erlittenen Magieschaden um 50%, lässt Euch dafür aber nicht mehr in die Verstohlenheit übergehen und hebt keine bewegungseinschränkenden Effekte auf." }
entries[1219779] = { ["name"] = "Seele des Akrobaten", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Akrobaten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure Finishing-Moves haben eine Chance von 20% pro Combopunkt, Euch durch den nächsten eintreffenden Nahkampfangriff innerhalb von 10 Sek. 20% weniger körperlichen Schaden erleiden zu lassen." }
entries[1219780] = { ["name"] = "Seele des protzigen Prüglers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des protzigen Prüglers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer Effekt 'Schläge abschwächen' wird jetzt außerdem jedes Mal ausgelöst, wenn Ihr einen Combopunkt erhaltet." }
entries[1219781] = { ["name"] = "Seele des schwarzen Gurts", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des schwarzen Gurts wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer Effekt 'Schläge abschwächen' gewährt Euch außerdem pro Stapel 20% mehr Rüstung von Gegenständen (bis zu einem Maximum von 100%)." }
entries[1219782] = { ["name"] = "Seele des Fechters", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Fechters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nDie Abklingzeit für Euren 'Parierdolch' wird jedes Mal abgeschlossen, wenn Euer Ziel ausweicht oder pariert." }
entries[1219783] = { ["name"] = "Seele des Säbelrasslers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Säbelrasslers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\n'Parierdolch' trifft nun 1 zusätzliches Ziel in der Nähe und lässt 'Finsterer Stoß' 10 Sek. lang 1 zusätzliches Ziel in der Nähe treffen. Diese zusätzlichen Treffer werden nicht von 'Klingenwirbel' dupliziert." }
entries[1219784] = { ["name"] = "Seele des Blutrünstigen", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Blutrünstigen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nWährend 'Parierdolch' aktiv ist, werdet Ihr zusätzlich um 15% des von 'Finsterer Stoß' verursachten Schadens geheilt. Überschüssige Heilung wird zu einer Blutbarriere, die Schaden in Höhe von bis zu 20% Eurer maximalen Gesundheit absorbiert." }
entries[1219785] = { ["name"] = "Seele des Transfusionisten", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Transfusionisten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\n'Aderlass' erzeugt 50% mehr Mana und 100% weniger Bedrohung." }
entries[1219786] = { ["name"] = "Seele des Verfeinerten", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Verfeinerten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht die kritische Trefferchance Eurer Zauber und Angriffe um 2%." }
entries[1219787] = { ["name"] = "Seele des Dezimierers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke" }
entries[1219788] = { ["name"] = "Seele des Fäulnisbringers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Fäulnisbringers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den Schaden Eurer regelmäßigen Zauber und Eurer Teufelswache um 10 + (5 * Combopunkte)%." }
entries[1219789] = { ["name"] = "Seele des Böswilligen", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Böswilligen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nRegelmäßiger Schaden Eurer Zauber 'Schattenflamme', 'Instabiles Gebrechen' und 'Fluch der Pein' sowie Schaden, den Eure Teufelswache verursacht, haben eine Chance von 4%, den Effekt 'Schattentrance' zu gewähren." }
entries[1219790] = { ["name"] = "Seele des Schattenbeschwörers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Schattenbeschwörers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nPro Effekt auf Eurem Ziel, der von Euch stammt, verursacht 'Schattenblitz' 10 + (5 * Combopunkte)% mehr Schaden, bis maximal 30 + (5 * Combopunkte)%." }
entries[1219791] = { ["name"] = "Seele des Chaosherolds", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke" }
entries[1219792] = { ["name"] = "Seele des Brandstifters", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Brandstifters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nJedes Mal, wenn Ihr ein Ziel mit 'Feuersbrunst' trefft, wird Euer Feuerschaden für 20 Sek. um 5% erhöht. Bis zu 2-mal stapelbar." }
entries[1219793] = { ["name"] = "Seele des infernalen Schäfers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des infernalen Schäfers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht die Angriffskraft und den Zauberschaden, den Euer Dämon durch Eure Attribute erlangt, um 20%." }
entries[1219794] = { ["name"] = "Seele des Dämonenfürsten", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke" }
entries[1219795] = { ["name"] = "Seele des dämonischen Exorzisten", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des dämonischen Exorzisten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\n'Verbannen' ist ein Spontanzauber und kann auf Euch selbst gewirkt werden, während Ihr ein Dämon seid. Ihr könnt 'Verbannen' nicht auf Euch selbst wirken, solange 'Vorahnung' auf Euch wirkt, und 'Verbannen' belegt Euch 1 Min. lang mit 'Vorahnung'." }
entries[1219796] = { ["name"] = "Seelen des Leidenden", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seelen des Leidenden wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nJedes Mal, wenn Ihr Schaden erleidet, erhaltet Ihr und Euer Diener Mana in Höhe des erlittenen Schadens, bis zu maximal 420 Mana pro Ereignis. Kann nur einmal alle paar Sekunden auftreten." }
entries[1219797] = { ["name"] = "Seele des Flammengespensts", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Flammengespensts wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure Treffer mit 'Schattenspalten' haben eine Chance von 20%, Euch einen Seelensplitter zu gewähren, die Abklingzeit von 'Seelenfeuer' abzuschließen und Euren nächsten Einsatz von 'Seelenfeuer' innerhalb von 10 Sek. zu einem Spontanzauber zu machen." }
entries[1219798] = { ["name"] = "Seele des Fleischverzehrers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Fleischverzehrers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nWährend Ihr einen Gegner innerhalb von 30 Metern anvisiert, gewährt 'Aderlass' Euch Mana auf Kosten der Gesundheit Eures Ziels, fügt ihm jedoch 50 + (5 * Combopunkte)% weniger Schaden zu. Das erlangte Mana bleibt unverändert." }
entries[1219799] = { ["name"] = "Seele des Abyssals", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Abyssals wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nWährend 'Metamorphose' aktiv ist, kosten Eure Angriffsfähigkeiten und Dämonenbeschwörungen keine Seelensplitter. Außerdem werden 15% Eurer maximalen Gesundheit geheilt, wenn Ihr einem Ziel mit 'Schattenbrand' Schaden zufügt." }
entries[1219800] = { ["name"] = "Seele des Leerengeborenen", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Leerengeborenen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nÜberschüssige Heilung, die Ihr auf Euch wirkt, wird in einen Schild umgewandelt, der Schaden absorbiert. Dieser Schild kann bis zu 30 + (5 * Combopunkte)% Eurer maximalen Gesundheit absorbieren und wird durch mehrere Heilungen gestapelt." }
entries[1219801] = { ["name"] = "Seele der Umbralklinge", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele der Umbralklinge wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Abklingzeit von 'Schattenspalten' um 1.5 Sek." }
entries[1219802] = { ["name"] = "Seele des Ritualisten", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Ritualisten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nDer Effekt von 'Dämonische Opferung' besteht nun fort, während Ihr einen aktiven Dämonenbegleiter habt, solange Ihr den geopferten Begleiter nicht erneut beschwört. Es kann immer nur ein Effekt von 'Dämonische Opferung' gleichzeitig aktiv sein." }
entries[1219803] = { ["name"] = "Seele des Schmerzverbreiters", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Schmerzverbreiters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nNach dem Einsatz von 'Schattenspalten' trifft Euer 'Sengender Schmerz' 6 Sek. lang 1 zusätzliches Ziel in Nahkampfreichweite." }
entries[1219804] = { ["name"] = "Seele des Irreführers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Irreführers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nIhr erzeugt 8 Sek. lang 100% mehr Bedrohung, nachdem Ihr 'Ablenkender Schuss' verwendet habt." }
entries[1219805] = { ["name"] = "Seele des Beutesuchers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Beutesuchers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nWenn Ihr einen Kreaturentyp verfolgt, fügt Ihr diesem Kreaturentyp 3% mehr Schaden zu." }
entries[1219806] = { ["name"] = "Seele des Scharfschützen", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Scharfschützen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure nächste Schussfähigkeit 12 Sek. nach 'Gezielter Schuss' verursacht 20% mehr Schaden." }
entries[1219807] = { ["name"] = "Seele des Gefahrenplünderers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Gefahrenplünderers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer 'Gezielter Schuss' fügt Zielen, die von einem Eurer Falleneffekte betroffen sind, 20% mehr Schaden zu." }
entries[1219808] = { ["name"] = "Seele des Wechslers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Wechslers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure schadensverursachenden Schussfähigkeiten verursachen 10% mehr Schaden, wenn der vorherige schadensverursachende Schuss ein anderer war als der aktuelle." }
entries[1219809] = { ["name"] = "Seele des Toxinologen", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Toxinologen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nDer Schaden Eurer Fähigkeit 'Schlangenbiss' wird über ihre normale Dauer um 25% Eurer Angriffskraft erhöht." }
entries[1219810] = { ["name"] = "Seele des Kopfgeldjägers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Kopfgeldjägers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den Schaden von 'Tödlicher Schuss' gegen Ziele, die nicht von Spielercharakteren kontrolliert werden, um 10%." }
entries[1219811] = { ["name"] = "Seele des Trickschützen", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Trickschützen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nDie Abklingzeit von 'Tödlicher Schuss' ist um 50% verringert. Wenn 'Schneller Tod' geprägt und 'Schnellfeuer' aktiv ist, hat 'Tödlicher Schuss' keine Abklingzeit und setzt gegen Ziele, die nicht von Spielercharakteren kontrolliert werden, 3-mal zusätzlich 'Tödlicher Schuss' mit Mindestreichweite und 30% Schaden ein." }
entries[1219812] = { ["name"] = "Seele des Tierpflegers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Tierpflegers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht die Angriffskraft, die Euer Wildtierbegleiter durch Eure Attribute erlangt, um 20%." }
entries[1219813] = { ["name"] = "Seele des Hundemeisters", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Hundemeisters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht die Fokusregeneration Eures Wildtierbegleiters um 20%." }
entries[1219814] = { ["name"] = "Haschende Geister" }
entries[1219815] = { ["name"] = "Seele des Alphazähmers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Alphazähmers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht die Fokusregeneration Eurer Tiere um 100%." }
entries[1219816] = { ["name"] = "Seele des Waidmanns", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Waidmanns wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer 'Mungobiss' verringert zudem die Ausweichchance seines Ziels um 1% und erhöht Eure Trefferchance 30 Sek. lang um 1%." }
entries[1219818] = { ["name"] = "Seele des Vergelters", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Vergelters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\n'Mungobiss' wird zudem für 5 Sek. aktiviert, wenn Euer Ziel pariert oder blockt, oder wenn Euer Nahkampfangriff verfehlt." }
entries[1219819] = { ["name"] = "Seele des Widerhalls", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Widerhalls wird dauerhaft in Eure Schulterstücke eingepflanzt:\n\n'Raptorstoß' erhöht den Schaden Eurer nächsten anderen Nahkampffähigkeit (mit Ausnahme von 'Zurechtstutzen') innerhalb von 5 Sek. um 20%." }
entries[1219820] = { ["name"] = "Seele des tödlichen Peitschers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des tödlichen Peitschers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den Schaden, den Eure Waffenhandwaffe durch 'Raptorstoß' und 'Flügeldrachenstoß' verursacht, um 20%." }
entries[1219821] = { ["name"] = "Seele des Kinetikers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Kinetikers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer regelmäßiger Schaden hat eine Chance von 5%, die Abklingzeit einer Eurer Stoßfähigkeiten abzuschießen. Es wird stets der Stoß mit der längsten verbleibenden Abklingzeit gewählt." }
entries[1219822] = { ["name"] = "Seele des Strategen", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Strategen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den regelmäßigen Schaden von 'Flügeldrachenstoß' um 50% und den maximalen Fokus Eures Begleiters um 50." }
entries[1219823] = { ["name"] = "Seele des Totschlägers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Totschlägers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den Aufprallschaden von 'Mungobiss' und allen Stoßfähigkeiten um 20%." }
entries[1219824] = { ["name"] = "Seele des beschleunigten Heilers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des beschleunigten Heilers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Zauberzeit von 'Blitzheilung' um 0.1 Sek. und die Zauberzeit von 'Große Heilung' um 0.2 Sek." }
entries[1219825] = { ["name"] = "Seele des Verfeinerten", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Verfeinerten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht die kritische Trefferchance Eurer Zauber und Angriffe um 2%." }
entries[1219826] = { ["name"] = "Seele des Zelebranten", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Zelebranten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht Eure kritische Trefferchance mit 'Gebet der Heilung' und 'Kreis der Heilung' um 25%." }
entries[1219827] = { ["name"] = "Seele des Treuen", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Treuen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nLässt 15% Eurer Manaregeneration während des Zauberwirkens weiterlaufen." }
entries[1219828] = { ["name"] = "Seele des Glücklichen", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Glücklichen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure regelmäßige Heilung hat eine Chance von 2%, dass Euer nächster Zauber mit einer Zauberzeit von weniger als 10 Sek. zu einem Spontanzauber wird." }
entries[1219829] = { ["name"] = "Seele des Resonanten", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Resonanten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nDie Zauber 'Kreis der Heilung' und 'Sühne' gewähren dem Ziel zusätzlich einen regelmäßigen Heilungseffekt, der im Verlauf von 15 Sek. 25% der normalen Menge heilt." }
entries[1219830] = { ["name"] = "Seele des Verehrers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Verehrers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\n'Gebet der Besserung' erhält 2 zusätzliche Aufladungen." }
entries[1219831] = { ["name"] = "Seele des Erzbischofs", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Erzbischofs wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\n'Kreis der Heilung' heilt nun das am schwersten verletzte Mitglied der Zielgruppe um 100% mehr Gesundheit." }
entries[1219832] = { ["name"] = "Seele des Bußfertigen", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Bußfertigen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Abklingzeit Eures Zaubers 'Sühne' um 6 Sek." }
entries[1219833] = { ["name"] = "Seele des Seelenwächters", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Seelenwächters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den von Eurem Zauber 'Machtwort: Schild' absorbierten Schaden um 10%." }
entries[1219834] = { ["name"] = "Seele des Zwielichtwandlers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Zwielichtwandlers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nIhr könnt 'Blitzheilung' in der Schattengestalt einsetzen." }
entries[1219835] = { ["name"] = "Seele des Gedankenstörers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Gedankenstörers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nKritische Treffer mit 'Gedankenschlag' verringern die Dauer Eures nächsten Einsatzes von 'Gedankenschinden' um 50% und erhöhen seinen Gesamtschaden um 25%." }
entries[1219836] = { ["name"] = "Seele des Todesboten", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Todesboten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Abklingzeit Eures Zaubers 'Schattenwort: Tod' um 6 Sek." }
entries[1219837] = { ["name"] = "Seele des Willensquells", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke" }
entries[1219838] = { ["name"] = "Seele des Zeloten", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Zeloten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nWährend 'Willensentzug' aktiv ist, verursacht Ihr 25% mehr Schattenschaden." }
entries[1219839] = { ["name"] = "Seele des unnachgiebigen Schänders", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des unnachgiebigen Schänders wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer 'Gedankenschinden' büßt keine Dauer mehr ein, wenn Ihr Schaden erleidet, und verschießt beim Einsatz einen kostenlosen 'Gedankenstachel' auf das Ziel." }
entries[1219840] = { ["name"] = "Seele des Verächters", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Verächters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer 'Gedankenstachel' ist ein Spontanzauber, verursacht 10% mehr Schaden und kann während der Kanalisierung eines anderen Zaubers eingesetzt werden." }
entries[1219841] = { ["name"] = "Seele des Seuchenbringers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Seuchenbringers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure Rune 'Schmerz und Leid' kann die Dauer von 'Verschlingende Seuche' erneuern." }
entries[1219842] = { ["name"] = "Seele des Nachhallenden", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Nachhallenden wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure Zeitenleuchtfeuer währen 20% länger." }
entries[1219843] = { ["name"] = "Seele des Chronoheilers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Chronoheilers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht alle chronomantische Heilung, die Ihr verursacht, um 10%." }
entries[1219844] = { ["name"] = "Seele des Temporalverlangens", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Temporalverlangens wird dauerhaft in Eure Schulterstücke eingepflanzt:\n\nJedes Mal, wenn Ihr ein Ziel mit Regeneration heilt, wird die verbleibende Abklingzeit von 'Zeit zurückdrehen' um 1 Sek. reduziert." }
entries[1219845] = { ["name"] = "Seele des Präkognitiven", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Präkognitiven wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer Zauber 'Arkane Geschosse' erstattet jedes Mal, wenn er Schaden verursacht, 10% seiner Grundmanakosten." }
entries[1219846] = { ["name"] = "Seele des Arkanisten", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Arkanisten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\n'Arkanschlag' erhält eine zusätzliche Chance von 10%, 'Geschosssalve' auszulösen, die sich jetzt genauso auf 'Regeneration' auswirkt wie auf 'Arkane Geschosse'." }
entries[1219847] = { ["name"] = "Seele des ewigen Hüters", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des ewigen Hüters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure durch 'Massenregeneration' erzeugten Zeitenleuchtfeuer halten nun 21 Sek. lang an." }
entries[1219848] = { ["name"] = "Seele des Zauberbinders", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Zauberbinders wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer 'Arkanschlag' erhöht Euren Schaden um zusätzlich 10% pro Stapel." }
entries[1219849] = { ["name"] = "Seele des Schutzformers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Schutzformers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer 'Manaschild', 'Feuerzauberschutz' und 'Frostzauberschutz' absorbieren 50% mehr Schaden und gewähren dem Ziel für 30 Sek. 'Zeitenleuchtfeuer'." }
entries[1219850] = { ["name"] = "Seele der Klauen des Winters", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele der Klauen des Winters wird dauerhaft in Eure Schulterstücke eingepflanzt:\n\nErhöht die Chance, dass Eure Rune 'Eisige Finger' ausgelöst wird, um zusätzliche 15%." }
entries[1219851] = { ["name"] = "Seele des Kryomanten", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Kryomanten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den verursachten Schaden Eurer Zauber 'Frostblitz' und 'Zauberfrostblitz' um 75%." }
entries[1219852] = { ["name"] = "Seele des Rufers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Rufers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nIhr seid gegen jeglichen Schaden immun, während Ihr 'Hervorrufung' kanalisiert." }
entries[1219853] = { ["name"] = "Seele des Elementaristen", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Elementaristen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nJedes Mal, wenn Ihr einen Zauber einer anderen Magieart wirkt, erhaltet Ihr 15 Sek. lang 1% erhöhten Schaden." }
entries[1219854] = { ["name"] = "Seele des magischen Rüstungsschmieds", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des magischen Rüstungsschmieds wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\n'Magische Rüstung' erhöht Eure Manaregeneration während des Zauberwirkens um zusätzliche 15%. 'Glühende Rüstung' erhöht Euren Zauberschaden und Heilung um 18. 'Eisrüstung' erhöht die Chance, 'Eisige Finger' auszulösen, um 20%." }
entries[1219855] = { ["name"] = "Seele des Zündlers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Zündlers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die von Euren Feuerzaubern verursachte Bedrohung um 20%." }
entries[1219856] = { ["name"] = "Seele der feurigen Konvergenz", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele der feurigen Konvergenz wird dauerhaft in Eure Schulterstücke eingepflanzt:\n\nEuer 'Pyroschlag' fügt Zielen, die vom regelmäßigen Effekt Eures Zaubers 'Feuerball' betroffen sind, 20% mehr Schaden zu." }
entries[1219857] = { ["name"] = "Seele der immerwährenden Flamme", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele der immerwährenden Flamme wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nDer regelmäßige Effekt Eures Zaubers 'Feuerball' erhöht den von ihm verursachten Schaden im Verlauf der Effektdauer um 100% seines Aufprallschadens." }
entries[1219858] = { ["name"] = "Seele des Pyromanen", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Pyromanen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer 'Feuerschlag' gewährt zusätzlich Eurem nächsten Feuerzauber für 10 Sek. eine um 50% erhöhte kritische Trefferchance." }
entries[1219859] = { ["name"] = "Seele des Entzünders", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke" }
entries[1219860] = { ["name"] = "Seele des Facklers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Facklers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nDer Schaden von 'Feuerball', 'Frostfeuerblitz' und 'Qualfeuerblitz' erhöht sich für jeden Eurer Feuereffekte auf dem Ziel um 4%, bis zu maximal 12%." }
entries[1219861] = { ["name"] = "Seele des makellosen Blockers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des makellosen Blockers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den Blockwert Eures Schildes um 30." }
entries[1219862] = { ["name"] = "Seele des Lichthüters", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Lichthüters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nHeilt Euch um 189 bis 211 Gesundheit, wenn Ihr blockt. Diese Heilung kann nur einmal alle paar Sekunden ausgelöst werden." }
entries[1219863] = { ["name"] = "Seele des strahlenden Verteidigers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des strahlenden Verteidigers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\n'Heiliger Schild' hat keine Aufladungen mehr und hält immer für die vollständige Effektdauer an. Zusätzlich wird der Schaden um 80% des Blockwerts Eures Schilds erhöht." }
entries[1219864] = { ["name"] = "Seele des Schildträgers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Schildträgers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht die zusätzliche Blockchance von 'Heiliger Schild' um 10%." }
entries[1219865] = { ["name"] = "Seele der Bastion", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele der Bastion wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nIhr erleidet 10% weniger Schaden, während 'Heiliger Schild' aktiv ist." }
entries[1219866] = { ["name"] = "Seele des Abrechners", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke" }
entries[1219867] = { ["name"] = "Seele des Gepanzerten", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Gepanzerten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer 'Segen des Refugiums' erhöht beim Einsatz bei Euch selbst zusätzlich alle Werte um 10%." }
entries[1219868] = { ["name"] = "Seele des Behüters", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Behüters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer 'Schild der Rechtschaffenen' macht Euren nächsten Einsatz von 'Heiliges Licht' zu einem Spontanzauber. Wenn er auf Euch selbst gewirkt wird, erstattet er 100% seiner Manakosten zurück und 'Vom Licht behütet' wirkt sich nicht darauf aus." }
entries[1219869] = { ["name"] = "Seele des Friedensbewahrers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Friedensbewahrers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht die Chance für Verbündete, Euer 'Richturteil des Lichts' und 'Richturteil der Weisheit' auszulösen, auf 70%." }
entries[1219870] = { ["name"] = "Seele des Verfeinerten", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Verfeinerten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht die kritische Trefferchance Eurer Zauber und Angriffe um 2%." }
entries[1219871] = { ["name"] = "Seele des Exemplars", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Exemplars wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nWenn Eure Fähigkeiten 'Lichtblitz', 'Heiliges Licht' oder 'Flamme des Glaubens' ein Ziel vollständig heilen, heilt Ihr zusätzlich auch alle seine Gruppenmitglieder um 189 bis 211 Gesundheit." }
entries[1219872] = { ["name"] = "Seele des Inquisitors", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Inquisitors wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht die kritische Trefferchance von 'Heiliger Schock' um 5%." }
entries[1219873] = { ["name"] = "Seele des Überlegenen", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Überlegenen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht Euren durch 'Weihe' verursachten Schaden um 50%." }
entries[1219874] = { ["name"] = "Seele des Dominus", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Dominus wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nDas Ziel Eurer 'Flamme des Glaubens' wird, wenn nicht Ihr selbst das seid, außerdem um 75% des Schadens geheilt, den Ihr mit 'Weihe', 'Exorzismus', 'Heiliger Schock', 'Heiliger Zorn' und 'Hammer des Zorns' verursacht." }
entries[1219875] = { ["name"] = "Seele des Verteidigers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Verteidigers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Abklingzeit von 'Göttliches Licht' um 25%." }
entries[1219876] = { ["name"] = "Seele des Altruisten", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Altruisten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure Heilungen beim Ziel Eurer 'Flamme des Glaubens' heilen zusätzlich das nächste verletzte verbündete Ziel um 90% des geheilten Werts." }
entries[1219877] = { ["name"] = "Seele des Richters", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Richters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\n'Richturteil des Lichts' und 'Richturteil der Weisheit' gewähren zusätzlich die Effekte von 'Richturteil des Kreuzfahrers'." }
entries[1219878] = { ["name"] = "Seele des Siegelträgers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Siegelträgers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure Fähigkeiten 'Siegel des Befehls', 'Siegel der Rechtschaffenheit', 'Siegel des Märtyrertums' und 'Sonnenlicht' verursachen 35% weniger Schaden, halten jetzt allerdings nach Einsatz eines weiteren Siegels noch 6 Sek. an, oder bis Ihr ein drittes Siegel einsetzt. 'Richturteil' kann mehrere Siegel auslösen, wenn sie aktiv sind." }
entries[1219879] = { ["name"] = "Seele des Vollstreckers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Vollstreckers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den verursachten Schaden Eurer Zauber 'Richturteil' um 5%, und Eure Siegel auf dem Ziel werden nicht mehr verbraucht. 'Richturteil' kann nach Aktivierung mehrere Siegel auslösen." }
entries[1219880] = { ["name"] = "Seele des Judikators", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Judikators wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Abklingzeit Eurer Fähigkeit 'Richturteil' um 5 Sek., verringert jedoch den Schaden Eurer Einsätze von 'Richturteil' um 45%." }
entries[1219881] = { ["name"] = "Seele des Aszendenten", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Aszendenten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer 'Richturteil' gewährt 8 Sek. lang 1% mehr Heiligschaden, bis zu 5-mal stapelbar." }
entries[1219882] = { ["name"] = "Seele des Maßreglers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Maßreglers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den Schaden von 'Kreuzfahrerstoß' um 150%." }
entries[1219883] = { ["name"] = "Seele des Exkommunikators", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Exkommunikators wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure einfachen Angriffe mit zweihändigen Nahkampfwaffen erhöhen den Schaden Eures nächsten Einsatzes von 'Exorzismus' innerhalb von 20 Sek. um 35%. Bis zu 3-mal stapelbar." }
entries[1219884] = { ["name"] = "Seele des Lichtbringers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Lichtbringers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den verursachten Schaden Eures Zaubers 'Heiliger Schock' um 50%." }
entries[1219885] = { ["name"] = "Seele des Verbannten", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Verbannten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Abklingzeit Eures Zaubers 'Exorzismus' um 3 Sek. und erhöht dessen verursachten Schaden um 75%." }
entries[1219886] = { ["name"] = "Seele des Templers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Templers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nWährend Ihr eine Einhandwaffe ausgerüstet habt, entfesselt Euer 'Kreuzfahrerstoß' den Effekt von 'Richturteil' bei Euren Siegeln, ohne dabei das Siegel aufzubrauchen." }
entries[1219887] = { ["name"] = "Seele des Windläufers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Windläufers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht Euer Angriffstempo für 3 Angriffe nach dem Parieren, Ausweichen oder Blocken um 30%." }
entries[1219888] = { ["name"] = "Seele des Schildmeisters", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Schildmeisters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nWenn Ihr pariert oder ausweicht, wird zusätzlich Eure Runenfähigkeit 'Schildmeisterschaft' aktiviert." }
entries[1219889] = { ["name"] = "Seele des Totembeschützers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Totembeschützers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer Totem der Steinhaut verringert zusätzlich den erlittenen körperlichen Schaden um 5% und Euer Totem der Windmauer verringert zusätzlich den erlittenen Magieschaden um 5%." }
entries[1219890] = { ["name"] = "Seele des Schockabsorbers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Schockabsorbers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer 'Flammenschock' gewährt auch eine 30% höhere Chance, zu blocken. Hält 5 Sek. lang an oder bis Ihr einen Angriff blockt." }
entries[1219891] = { ["name"] = "Seele des spirituellen Bollwerks", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des spirituellen Bollwerks wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nJedes Mal wenn Ihr blockt, wird Euer Blockwert 6 Sek. lang um 10% Eures Zauberschadens erhöht. Bis zu 3-mal stapelbar." }
entries[1219892] = { ["name"] = "Seele des Mahlstrombringers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Mahlstrombringers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nJedes Mal, wenn Ihr einen Angriff blockt, habt Ihr eine Chance von 50%, dass Eure Rune 'Waffe des Mahlstroms' ausgelöst wird." }
entries[1219893] = { ["name"] = "Seele des Lavawandlers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Lavawandlers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nWenn Ihr einem Ziel mit 'Sturmschlag', 'Lavaeruption' oder 'Schmelzschlag' Schaden zufügt, verringert das zusätzlich Euren erlittenen Schaden für 10 Sek. um 10%." }
entries[1219894] = { ["name"] = "Seele des wahren Alphas", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des wahren Alphas wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nWenn Ihr 'Geist des Alphas' auf Euch selbst wirkt, werden zusätzlich Eure Gesundheit um 5%, die von Euch erzeugte Bedrohung um 25% und sämtlicher von Euch verursachter Schaden um 5% erhöht." }
entries[1219895] = { ["name"] = "Seele des Totemhüters", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Totemhüters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nDer Radius Eurer Totems, die auf verbündete Ziele wirken, ist auf 40 Meter erhöht." }
entries[1219896] = { ["name"] = "Seele der Ahnen", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele der Ahnen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nWenn die Zauber 'Welle der Heilung', 'Geringe Welle der Heilung' oder 'Springflut' gewirkt werden, besteht eine Chance von 25%, Mana zu gewinnen. Der Managewinn entspricht 35% der Grundkosten des Zaubers." }
entries[1219897] = { ["name"] = "Seele des Geisterwebers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Geisterwebers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure Zauber 'Welle der Heilung' springen auf bis zu zwei zusätzliche Ziele über. Bei jedem Sprung reduziert sich die Effektivität der Heilung um 60% und der Zauber springt auf bis zu 2 zusätzliche Ziele über." }
entries[1219898] = { ["name"] = "Seele des Wasserwandlers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Wasserwandlers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure kritischen Schadens- und Heilungstreffer von nicht regelmäßigen Effekten haben jetzt eine Chance von 100%, Euren 'Wasserschild' auszulösen. Dafür verbrauchen sie weder eine Aufladung noch lösen sie die Abklingzeit aus." }
entries[1219899] = { ["name"] = "Seele des Sturmpflegers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Sturmpflegers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer 'Kettenblitzschlag' heilt jetzt auch das Ziel Eures letzten Zaubers 'Erdschild' um 100% des verursachten Schadens." }
entries[1219900] = { ["name"] = "Seele des Elementarsehers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Elementarsehers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht die Heilung von 'Kettenheilung' sowie den Schaden von 'Kettenblitzschlag' um 20%." }
entries[1219901] = { ["name"] = "Seele des Vitalisten", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Vitalisten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure 'Springflut' erhöht den von 'Kettenheilung' geheilten Wert um zusätzlich 25%." }
entries[1219902] = { ["name"] = "Seele des Geisterheilers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Geisterheilers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Zauberzeit von 'Kettenheilung' um 0.5 Sek." }
entries[1219903] = { ["name"] = "Seele des Verfeinerten", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Verfeinerten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht die kritische Trefferchance Eurer Zauber und Angriffe um 2%." }
entries[1219904] = { ["name"] = "Seele des Häuptlings", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke" }
entries[1219905] = { ["name"] = "Seele des Zorngeladenen", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Zorngeladenen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure Chance, 'Statischer Schock' auszulösen, ist um 12% erhöht (6% beim Führen von zwei Waffen)." }
entries[1219906] = { ["name"] = "Seele des Sturmbrechers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Sturmbrechers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den Waffenhandschaden von 'Sturmschlag' um 50%." }
entries[1219907] = { ["name"] = "Seele des Orkans", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Orkans wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nWährend 'Statischer Schock' eingraviert ist, erhält Euer 'Blitzschlagschild' nun immer, wenn Ihr ein Ziel mit 'Blitzschlag' oder 'Kettenblitzschlag' trefft, eine Aufladung, bis zu einem Maximum von 9 Aufladungen. Zusätzlich kann Euer 'Blitzschlagschild' nun kritischen Schaden verursachen, wenn 'Statischer Schock' eingraviert ist." }
entries[1219908] = { ["name"] = "Seele des seismischen Schmetterers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des seismischen Schmetterers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den Schaden von 'Sturmschlag' und 'Lavapeitsche' um 50%. Dieser Effekt wird bei Verwendung einer Zweihandwaffe auf 100% erhöht." }
entries[1219909] = { ["name"] = "Seele des Flammenbringers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Flammenbringers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure kritischen Treffer mit 'Sturmschlag', 'Lavapeitsche' und 'Lavaeruption' lassen Euer Ziel brennen, was ihm 30% des verursachten Schadens im Verlauf von 4 Sek. zufügt." }
entries[1219910] = { ["name"] = "Seele des Vulkans", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Vulkans wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nKritische Treffer mit 'Blitzschlag' haben eine Chance von 35%, die Abklingzeiten von 'Lavaeruption' und 'Kettenblitzschlag' abzuschließen und Euren nächsten Einsatz von 'Lavaeruption' oder 'Kettenblitzschlag' innerhalb von 10 Sek. zu einem Spontanzauber zu machen." }
entries[1219911] = { ["name"] = "Seele der tobenden Flamme", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele der tobenden Flamme wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\n'Lavaeruption' setzt zusätzlich die Dauer Eures Effekts 'Flammenschock' auf dem Ziel wieder auf 12 Sek." }
entries[1219912] = { ["name"] = "Seele des Elementarmeisters", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke" }
entries[1219913] = { ["name"] = "Seele des Stammesangehörigen", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Stammesangehörigen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nDer Effekt 'Treuer Beta' Eurer Fähigkeit 'Geist des Alphas' erhöht jetzt auch den Feuer-, Frost- und Naturschaden um 5 + (5 * Combopunkte)%." }
entries[1219914] = { ["name"] = "Seele des Geisterführers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Geisterführers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nWährend 'Freizaubern' aktiv ist, verursacht Ihr 15 + (5 * Combopunkte)% mehr nichtkörperlichen Schaden." }
entries[1219915] = { ["name"] = "Seele des Ältesten", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke" }
entries[1219916] = { ["name"] = "Seele der Elemente", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele der Elemente wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den Schadensbonus der kritischen Treffer Eurer Feuer-, Frost- und Naturzauber um 60%." }
entries[1219917] = { ["name"] = "Seele des Lavaweisen", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Lavaweisen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nDer Schaden Eurer 'Lavaeruption' wird um einen Prozentsatz in Höhe Eurer kritischen Zaubertrefferchance erhöht." }
entries[1219918] = { ["name"] = "Seele des Ahnenwächters", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Ahnenwächters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht Eure Chance, Angriffe mit einem Schild zu blocken, um 10%." }
entries[1219919] = { ["name"] = "Seele des Verderbten", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Verderbten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht die Chance, dass Eure Rune 'Kraftwoge' ausgelöst wird, um zusätzliche 5%." }
entries[1219920] = { ["name"] = "Seele der sanften Pfote", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele der sanften Pfote wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nIhr könnt in 'Bärengestalt' oder 'Terrorbärengestalt' 'Wiedergeburt' und 'Anregen' wirken." }
entries[1219921] = { ["name"] = "Seele des Wilden", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Wilden wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Abklingzeit von 'Wutanfall' um 30 Sek. und die Fähigkeit verringert nicht länger Eure Rüstung." }
entries[1219922] = { ["name"] = "Seele des Wandlers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Wandlers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\n'Bärengestalt' und 'Terrorbärengestalt' erhöhen alle von Euch erzeugte Bedrohung um zusätzliche 20%, und 'Ducken' entfernt jetzt Eure gesamte Bedrohung gegen das Ziel, hat aber eine 20 Sek. längere Abklingzeit." }
entries[1219923] = { ["name"] = "Seele des Territorialen", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Territorialen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer 'Prankenhieb' (Bär) sorgt außerdem dafür, dass Euer 'Zermalmen' in den nächsten 6 Sek. 1 zusätzliches Ziel trifft." }
entries[1219924] = { ["name"] = "Seele der Bestie", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele der Bestie wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure Fähigkeiten 'Zerfleischen' (Bär), 'Prankenhieb' (Bär), 'Zermalmen' und 'Aufschlitzen' haben eine um 5% erhöhte kritische Trefferchance bei Zielen, die von Eurem 'Aufschlitzen' betroffen sind." }
entries[1219925] = { ["name"] = "Seele des Aufschlitzers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Aufschlitzers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer 'Prankenhieb' weitet Euer 'Aufschlitzen' von Eurem Primärziel auf andere von ihm getroffene Ziele aus." }
entries[1219926] = { ["name"] = "Seele des Rasenden", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Rasenden wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nJedes Mal, wenn Ihr in Terrorbärengestalt ausweicht, erhöht sich der Schaden Eures nächsten Einsatzes von 'Zerfleischen' oder 'Prankenhieb' um 10%. Bis zu 5-mal stapelbar." }
entries[1219927] = { ["name"] = "Seele des Zerfleischers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Zerfleischers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Abklingzeit von 'Zerfleischen' (Bär) um 1.5 Sek." }
entries[1219928] = { ["name"] = "Seele des Anregers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Anregers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nWenn Ihr 'Anregen' auf einen anderen Spielercharakter wirkt, ist auch Euer Charakter betroffen." }
entries[1219929] = { ["name"] = "Seele des Nährers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Nährers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nWenn Ihr Eure Zauber 'Heilende Berührung' oder 'Pflege' wirkt, erhaltet Ihr mit einer Chance von 25% Mana in Höhe von 35% der Grundkosten des Zaubers." }
entries[1219930] = { ["name"] = "Seele des Gelassenen", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Gelassenen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Abklingzeit von 'Gelassenheit' um 100% und erhöht ihre Heilung um 100%." }
entries[1219931] = { ["name"] = "Seele des Traumwandlers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Traumwandlers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nKritische Treffer Eurer Heilzauber lösen den Effekt 'Traumzustand' aus und gewähren Euch 8 Sek. lang 50% Manaregeneration, während Ihr Zauber wirkt." }
entries[1219932] = { ["name"] = "Seele des Hainhüters", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Hainhüters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nDie kritischen Treffer Eurer nicht regelmäßigen Zauber verringern die Zauberzeit Eures nächsten Einsatzes von 'Heilende Berührung', 'Pflege' und 'Nachwachsen' um 0.5 Sek." }
entries[1219933] = { ["name"] = "Seele des gefiederten Weisen", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des gefiederten Weisen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht die Heilung durch 'Wildwuchs' um 10%. Darüber hinaus lässt sich 'Wildwuchs' nun in der Mondkingestalt einsetzen, und seine Heilung wird in dieser Gestalt zusätzlich um 50% erhöht." }
entries[1219934] = { ["name"] = "Seele des gütigen Sehers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des gütigen Sehers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Abklingzeit von 'Wiedergeburt' und 'Anregen' um 65%." }
entries[1219935] = { ["name"] = "Seele des Lebenswebers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Lebenswebers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure kritischen Heilungen mit 'Heilende Berührung', 'Nachwachsen' und 'Pflege' heilen das Ziel sofort um weitere 50% der von ihnen hervorgerufenen Heilung." }
entries[1219936] = { ["name"] = "Seele des Erleuchters", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Erleuchters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer 'Feenfeuer (Tiergestalt)' erhöht zudem die Chance für alle Angriffe, das Ziel zu treffen, 40 Sek. lang um 1%." }
entries[1219937] = { ["name"] = "Seele der räuberischen Instinkte", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele der räuberischen Instinkte wird dauerhaft in Eure Schulterstücke eingepflanzt:\n\nDer regelmäßige Schaden Eures 'Krallenhieb' und 'Zerfetzen' kann nun kritische Treffer verursachen." }
entries[1219938] = { ["name"] = "Seele des Zerfetzers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Zerfetzers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer 'Zerfetzen' und 'Wilder Biss' haben eine Chance von 20% pro ausgegebenem Combopunkt, die Dauer von 'Wildes Brüllen' wieder auf den ursprünglichen Wert aufzufrischen." }
entries[1219939] = { ["name"] = "Seele der Klaue", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele der Klaue wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht die Dauer von 'Krallenhieb' um 3 Sek. und den regelmäßigen Schaden um 10%." }
entries[1219940] = { ["name"] = "Seele des Stolzes", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Stolzes wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure kritische Trefferchance ist um 15% erhöht, während 'Tigerfuror' aktiv ist." }
entries[1219941] = { ["name"] = "Seele des Barbarischen", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Barbarischen wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure Fähigkeiten 'Schreddern', 'Wilder Biss' und 'Zermalmen' (Katze) verursachen 10% mehr Schaden pro Blutungseffekt auf dem Ziel, bis zu einer maximalen Steigerung von 20%." }
entries[1219942] = { ["name"] = "Seele des Fieberhaften", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Fieberhaften wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEuer 'Schreddern' hat keine Positionierungsvoraussetzung mehr, verursacht aber 5% mehr Schaden, wenn Ihr Euch hinter dem Ziel befindet." }
entries[1219943] = { ["name"] = "Seele des Ausbluters", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Ausbluters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure kritischen Treffer mit 'Zerfleischen', 'Schreddern' und 'Wilder Biss' lassen Euer Ziel bluten und fügen ihm 30% des verursachten Schadens im Verlauf der nächsten 4 Sek. zu." }
entries[1219944] = { ["name"] = "Seele des Dornenhüters", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Dornenhüters wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nDurch 'Dornen' verursachter Schaden um 100% und Wirkungsdauer um 200% erhöht." }
entries[1219945] = { ["name"] = "Seele des Irren", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Irren wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht Eure Chance auf Treffer mit Zaubern und Angriffen um 3%." }
entries[1219946] = { ["name"] = "Seele des Sternenrufers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Sternenrufers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Abklingzeit von 'Sternenregen' um 50%." }
entries[1219947] = { ["name"] = "Seele der Nacht", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele der Nacht wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den Schadensradius und den verursachten Schaden der Sterne von 'Sternenregen' und 'Hurrikan' um 25%." }
entries[1219948] = { ["name"] = "Seele der Bewahrer", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele der Bewahrer wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nEure Einsätze von 'Zorn' haben eine Chance von 10%, ein Wäldchen aus 3 Treants zu beschwören, die Euer Ziel 15 Sek. lang angreifen." }
entries[1219949] = { ["name"] = "Seele des Wutentbrannten", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Wutentbrannten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nKritische Treffer von 'Zorn' haben eine Chance von 50%, dass Euer nächstes 'Sternenfeuer' 10% mehr Schaden verursacht und sich bis zu 3-mal stapeln lässt." }
entries[1219950] = { ["name"] = "Seele des Anmutigen", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke" }
entries[1219951] = { ["name"] = "Seele des astralen Aszendenten", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des astralen Aszendenten wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht den Schadensbonus für kritische Treffer Eurer Zauber 'Sternenfeuer', 'Sternensog' und 'Zorn' um 60%." }
entries[1219952] = { ["name"] = "Seele des Kometenrufers", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Kometenrufers wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nVerringert die Zauberzeit und globale Abklingzeit von 'Sternenfeuer' um 0.5 Sek." }
entries[1219953] = { ["name"] = "Seele des Waldes", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele des Waldes wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nErhöht die kritische Trefferchance von 'Zorn' um 10%." }
entries[1219954] = { ["name"] = "Seele der animalischen Expertise", ["text"] = "Wirken in 3 sek.\nBenötigt Schulterstücke\nDie Seele der animalischen Expertise wird dauerhaft in Eure Schulterrüstung eingepflanzt:\n\nDie Chance, dass Eure Nahkampfangriffe pariert werden oder ihnen ausgewichen wird, ist um 5% verringert." }
entries[1219955] = { ["name"] = "Seelengravur", ["text"] = "Sofort\nDie Seele eines gefallenen Kriegers kann in diesen Platz eingraviert werden." }
