entries[1219957] = { ["name"] = "Seele des Taktikers", ["text"] = "Nachdem Ihr die Haltung wechselt, sind die Wutkosten Eurer nächsten Offensivfähigkeit um 10 verringert." }
entries[1219958] = { ["name"] = "Seele des Kriegsveteranen", ["text"] = "Nach Verlassen einer Haltung könnt Ihr 15 Sek. lang noch Fähigkeiten nutzen, die diese Haltung erfordern." }
entries[1219959] = { ["name"] = "Seele des Kriegsveteranen" }
entries[1219960] = { ["name"] = "Seele des Kampfvoraussehers", ["text"] = "Wenn Ihr eine Haltung einnehmt, erhaltet Ihr für 15 Sek. einen weiteren Vorteil:\n\nKampfhaltung/Gladiatorhaltung: Verursachter Schaden um 5% erhöht.\n\nBerserkerhaltung: Kritische Trefferchance um 5% erhöht.\n\nVerteidigungshaltung: Erlittener körperlicher Schaden um 5% verringert." }
entries[1219961] = { ["name"] = "Seele des Kampfvoraussehers" }
